    // 动词前缀（“正在发送 …”“已发送 …”），与桌面版 shared/i18n.js 一致
    private val verbs = listOf(
        "Sending" to "正在发送", "Sent" to "已发送", "Receiving" to "正在接收", "Received" to "已接收",
        "Getting" to "正在获取", "Playing" to "正在播放", "Opening" to "正在打开", "Showing" to "正在显示",
