        "Downloading" to "正在下载", "Installing" to "正在安装", "Waking" to "正在唤醒", "Removing" to "正在移除",
        "Changing" to "正在更改", "Starting" to "正在启动", "Checking" to "正在检查", "Looking" to "正在查找",
        "Reconnecting" to "正在重新连接", "Pairing" to "正在配对", "Loading" to "正在加载", "Restarting" to "正在重启",
        "Connecting" to "正在连接", "Disconnecting" to "正在断开", "Uploading" to "正在上传", "Saving" to "正在保存",
        "Disconnect" to "断开", "Connect" to "连接", "Download" to "下载", "Install" to "安装",
        "Show" to "显示", "Open" to "打开", "Share" to "共享", "Send" to "发送", "Take Over" to "接管",
    )

    private val cjk = Regex("[\\u4e00-\\u9fff]")

    fun t(s: String): String {
        if (s.isEmpty()) return s
        m[s]?.let { return it }
        if (cjk.containsMatchIn(s)) return s
        for ((en, zhv) in verbs) {
            if (s.startsWith(en + " ")) return zhv + " " + s.substring(en.length + 1)
        }
        return s
    }
}

@Composable
fun Text(
    text: String,
    modifier: Modifier = Modifier,
    color: Color = Color.Unspecified,
    fontSize: TextUnit = TextUnit.Unspecified,
    fontStyle: FontStyle? = null,
    fontWeight: FontWeight? = null,
    fontFamily: FontFamily? = null,
    letterSpacing: TextUnit = TextUnit.Unspecified,
    textDecoration: TextDecoration? = null,
    textAlign: TextAlign? = null,
    lineHeight: TextUnit = TextUnit.Unspecified,
    overflow: TextOverflow = TextOverflow.Clip,
    softWrap: Boolean = true,
    maxLines: Int = Int.MAX_VALUE,
    minLines: Int = 1,
    onTextLayout: ((TextLayoutResult) -> Unit)? = null,
    style: TextStyle = LocalTextStyle.current,
) = M3Text(
    text = Zh.t(text), modifier = modifier, color = color, fontSize = fontSize, fontStyle = fontStyle,
    fontWeight = fontWeight, fontFamily = fontFamily, letterSpacing = letterSpacing,
    textDecoration = textDecoration, textAlign = textAlign, lineHeight = lineHeight,
    overflow = overflow, softWrap = softWrap, maxLines = maxLines, minLines = minLines,
    onTextLayout = onTextLayout, style = style,
)
